import unittest
from leap import is_leap


class T(unittest.TestCase):
    def test(self):
        for y, want in ((2024, True), (1900, False), (2000, True), (2023, False), (2100, False)):
            self.assertEqual(is_leap(y), want, y)


unittest.main()
